// --- /stats ---
if (cmd === 'stats') {
  const byCat = {}, byPrio = {}, byPlat = {}, byLevel = {}, byStat = {};
  for (const t of pool) {
    byCat[t.category||'autre'] = (byCat[t.category||'autre']||0) + 1;
    byPrio[t.priority||'p4'] = (byPrio[t.priority||'p4']||0) + 1;
